// Iron Jetpacks: tiers from diamond up need Alchemy's Quicksilver, netherite also Ignis Perpetuus (docs/gates.md).
// Jetpack, thruster and capacitor recipes are generated by Iron Jetpacks at runtime and KubeJS cannot see them,
// but every thruster takes the coil of its tier: diamond and emerald the elite coil, netherite the ultimate coil.
// So the gate sits on the coils. The creative jetpack has no crafting material and no recipe.
ServerEvents.recipes(event => {
  event.remove({ id: 'ironjetpacks:elite_coil' })
  event.shaped('ironjetpacks:elite_coil', ['QDR', 'DSD', 'RDQ'], {
    Q: 'servus_alchemy:quicksilver',
    D: '#c:gems/diamond',
    R: '#c:dusts/redstone',
    S: '#c:rods/wooden'
  }).id('servus:gates/elite_coil')

  event.remove({ id: 'ironjetpacks:ultimate_coil' })
  event.shaped('ironjetpacks:ultimate_coil', ['QDR', 'DSD', 'RDI'], {
    Q: 'servus_alchemy:quicksilver',
    I: 'servus_alchemy:ignis_perpetuus',
    D: '#c:gems/emerald',
    R: '#c:dusts/redstone',
    S: '#c:rods/wooden'
  }).id('servus:gates/ultimate_coil')
})
